// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · İletişim bilimleri, medya kuramları ve medya okuryazarlığı (gündem belirleme, suskunluk sarmalı, çerçeveleme, yankı odası, dezenformasyon) (kolay).
const ozSocialscience16Kolay = <(String, String, List<String>, String)>[
  ('Claude Shannon ve Warren Weaver tarafından Bell Telefon Laboratuvarları bünyesinde geliştirilen klasik iletişim modelinin temel çıkış amacı nedir?', 'Telefon hatlarındaki sinyal iletim verimliliğini matematiksel olarak ölçmek', ['Seçmenlerin siyasal kampanya mesajlarına verdiği duygusal tepkileri sınıflandırmak', 'Televizyon dizilerinin uzun vadeli kültürel kalıplar üzerindeki etkisini saptamak', 'Gazete yazı işleri müdürlerinin haber eleme ölçütlerini sosyolojik açıdan açıklamak'], 'Shannon ve Weaver 1949 tarihli modellerini telekomünikasyon kanallarında bilginin en az kayıpla ve en yüksek kapasiteyle aktarılmasını sağlamak amacıyla mühendislik temelli olarak tasarlamıştır.'),
  ('Bir konferans salonunda konuşmacının sunumu sürerken dışarıdaki yol çalışmasından gelen asfalt kırma makinesi sesi nedeniyle dinleyicilerin cümleleri duyamaması hangi kavramla açıklanır?', 'Fiziksel gürültü', ['Anlamsal gürültü', 'Psikolojik savunma', 'Bilişsel uyumsuzluk'], 'İletişim kanalında dış ortamdan kaynaklanan ve sinyalin alıcıya ulaşmasını mekanik ya da akustik biçimde güçleştiren somut dışsal engeller fiziksel gürültü olarak adlandırılır.'),
  ('Hekimin hastasına tanı koyarken Latince tıbbi terimler kullanması sonucunda hastanın işittiği sözcüklere hiçbir anlam verememesi ne tür bir iletişim aksaklığıdır?', 'Anlamsal gürültü', ['Fizyolojik gürültü', 'Mekanik parazit', 'Eşik bekçiliği'], 'Kaynağın kullandığı simge, jargon veya uzmanlık dilinin alıcının sözcük dağarcığıyla örtüşmemesi yüzünden anlamın çözülememesi semantik (anlamsal) gürültüdür.'),
  ('Zihindeki soyut bir düşüncenin, duygunun ya da bilginin karşı tarafın algılayabileceği sözcük, rakam, jest veya görsel işaret dizgelerine dönüştürülmesi işlemine ne ad verilir?', 'Kodlama', ['Kodaçımı', 'Yansıma', 'Kanalize etme'], 'Kaynağın iletmek istediği anlamı ortak bir simge sistemine (dil, yazı, beden hareketi vb.) dökerek mesaj hâline getirmesi kodlama (encoding) aşamasıdır.'),
  ('Edward T. Hall\'un mesafe sınıflandırmasında yalnızca çok yakın aile bireylerinin ve duygusal partnerlerin girmesine izin verilen, ten temasından yaklaşık kırk beş santimetreye kadar uzanan bölge hangisidir?', 'Mahrem mesafe', ['Sosyal mesafe', 'Kamusal mesafe', 'Kurumsal mesafe'], 'Hall\'a göre 0-45 cm arası mahrem alan olup kişinin en yoğun duygusal ve fiziksel koruma sınırını oluşturur; davetsiz girilmesi rahatsızlık ve tehdit algısı yaratır.'),
  ('Şiddetli migren ağrısı veya ileri derecede işitme kaybı yaşayan bir öğrencinin sınıftaki dersi takip etmekte zorlanması iletişim sürecindeki hangi engel türüne örnektir?', 'Fizyolojik gürültü', ['Kültürel gürültü', 'Yapısal gürültü', 'Simgesel gürültü'], 'Kaynak ya da alıcının biyolojik ve bedensel durumundan (açlık, yorgunluk, ağrı, görme veya işitme bozukluğu) ileri gelen engeller fizyolojik gürültü olarak tanımlanır.'),
  ('Bir öğretmenin anlattığı konunun anlaşılıp anlaşılmadığını öğrencilerin çatılan kaşlarından ve boş bakışlarından fark ederek konuyu farklı bir örnekle yeniden açıklaması hangi öğenin işlevidir?', 'Geri bildirim', ['Ön-kodlama süzgeci', 'Doğrusal aktarım', 'Entropi artışı'], 'Alıcının kaynağın mesajına sözlü ya da sözsüz olarak verdiği yanıt geri bildirimdir; kaynağın mesajını yeniden düzenlemesine ve iletişimin çift yönlü olmasına imkân tanır.'),
  ('Ray Birdwhistell\'in öncülüğünü yaptığı ve yüz ifadeleri, baş hareketleri, duruş (postür) ile el-kol jestlerinin iletişimsel anlamlarını çözümleyen disiplin nasıl adlandırılır?', 'Kinesik', ['Proksemik', 'Semantik', 'Fonoloji'], 'Kinesik, beden hareketlerinin sözsüz iletişimdeki rolünü sistematik biçimde inceleyen çalışma alanıdır.'),
  ('Sözlü iletişimle karşılaştırıldığında yazılı iletişimin kurumsal ve hukuki yaşamda tercih edilmesini sağlayan en belirgin üstünlüğü nedir?', 'Kalıcı olması, arşivlenebilmesi ve sonradan nesnel kanıt olarak incelenebilmesi', ['Anında jest ve mimiklerle desteklenerek duygusal yoğunluğu artırması', 'Okuma yazma bilmeyen topluluklara da eşit hızda ulaşabilmesi', 'Gönderildiği anda alıcının yüz ifadesinden eşzamanlı geri bildirim sağlaması'], 'Yazılı iletişimde geri bildirim gecikmeli olsa da metnin kalıcılığı, denetlenebilirliği ve resmî belge niteliği uzun vadeli kurumsal hafıza için vazgeçilmezdir.'),
  ('Bir iş görüşmesinde adayın \'Çok heyecanlı değilim, gayet rahatım\' derken ellerini sürekli ovuşturması ve ayaklarını hızla sallaması durumunda gözlemciler genellikle hangi kanala daha çok güvenir?', 'İstem dışı gerçekleşme olasılığı daha yüksek olan sözsüz beden ipuçlarına', ['Adayın özgeçmiş dosyasında yer alan standart matbu cümlelere', 'Görüşme odasındaki mobilyaların mimari yerleşim düzenine', 'Yalnızca söylenen sözcüklerin dilbilgisel doğruluğuna'], 'Sözlü mesaj ile sözsüz mesaj çeliştiğinde, beden dili ve otonom tepkiler bilinçli denetime daha az açık olduğundan alıcılar sözsüz kanala inanma eğilimindedir.'),
  ('Roland Barthes\'ın göstergebilimsel çözümlemesinde bir kırmızı gül fotoğrafının ilk bakışta yalnızca \'kırmızı taç yapraklı bir bitki\' olarak algılanması hangi anlam düzeyidir?', 'Düzanlam (denotasyon)', ['Yananlam (konotasyon)', 'İdeolojik mit', 'Metonimik kayma'], 'Barthes\'a göre düzanlam göstergenin herkesçe üzerinde uzlaşılan ilk, nesnel ve sözlüksel karşılığıdır; tutkulu aşkı çağrıştırması ise kültürel yananlam (konotasyon) düzeyidir.'),
  ('İnsanın kendi iç dünyasında düşüncelerini tartması, karar vermesi, iç konuşma yapması ve duygularını anlamlandırması iletişim türlerinden hangisinin kapsamına girer?', 'Kişi içi (intrapersonal) iletişim', ['Kişilerarası (interpersonal) iletişim', 'Örgüt içi dikey iletişim', 'Kitle iletişimi'], 'Kişi içi iletişim, kaynak ve alıcının aynı birey olduğu, zihinsel süreçler ve içsel diyalog üzerinden yürüyen temel iletişim düzeyidir.'),
  ('Bir kişinin karşı tarafa karşı beslediği derin kıskançlık, yoğun öfke veya aşırı kaygı yüzünden söylenen olumlu bir cümleyi bile saldırı olarak algılaması hangi gürültü türüdür?', 'Psikolojik gürültü', ['Fiziksel gürültü', 'Teknik gürültü', 'Akustik gürültü'], 'Bireyin zihinsel ön kabulleri, duygusal çalkantıları, korkuları ve tutumlarından kaynaklanan algılama çarpıklıkları psikolojik gürültü olarak değerlendirilir.'),
  ('Üniforma, rozet, gözlük çerçevesi, makam odası dekorasyonu ve takılar aracılığıyla statü ya da kimlik mesajı verilmesi sözsüz iletişimde hangi başlık altında incelenir?', 'Nesne dili ve artefakt kullanımı', ['Paralinguistik ses dizgesi', 'Fonemik boğumlama', 'Sözdizimsel dönüşüm'], 'Bireylerin bedenlerinde taşıdıkları giysi ve aksesuarlar ile çevrelerini düzenledikleri eşyalar (artefaktlar) kimlik, meslek ve toplumsal konum hakkında sessiz iletiler yayar.'),
  ('Doğrusal (tek yönlü) iletişim modellerinin en belirgin kuramsal sınırlılığı aşağıdakilerden hangisidir?', 'Alıcıyı edilgen bir hedef gibi konumlandırıp geri bildirim ve bağlamı ihmal etmesi', ['Kaynak ve kanal kavramlarına model içinde hiç yer vermemesi', 'Yalnızca yüz yüze yapılan samimi aile sohbetlerini açıklamaya çalışması', 'Mesajın oluşturulmasında dilin rolünü tümüyle reddetmesi'], 'Doğrusal modeller iletişimi kaynaktan alıcıya doğru akan tek yönlü bir ok gibi ele aldığından alıcının aktif yorumlama gücünü ve karşılıklı etkileşimi gözden kaçırır.'),
  ('Bir miting meydanında kürsüdeki konuşmacı ile dinleyici topluluğu arasında bırakılan üç buçuk metreden daha geniş açıklık proksemik açıdan nasıl adlandırılır?', 'Kamusal mesafe', ['Kişisel mesafe', 'Mahrem mesafe', 'İçsel mesafe'], 'Kamusal mesafe (360 cm ve üzeri), konferansçıların, siyasetçilerin veya sahne sanatçılarının geniş gruplara hitap ederken kullandıkları en dış çemberdir.'),
  ('Aristoteles\'in ikna kuramında bir yardım kampanyası konuşmacısının istatistiksel tablolar yerine depremzede bir çocuğun hüzünlü öyküsünü anlatarak bağış toplamaya çalışması neye dayanır?', 'Pathos', ['Logos', 'Ethos', 'Telos'], 'Pathos, hedef kitlenin merhamet, korku, umut veya üzüntü gibi duygularına hitap ederek tutum değişikliği yaratma stratejisidir.'),
  ('Mahkeme salonunda savunma avukatının duygusal çağrılardan kaçınıp yalnızca kamera kayıtları, saat çizelgeleri ve tümdengelimsel çıkarımlar sunması hangi ikna boyutunu öne çıkarır?', 'Logos', ['Pathos', 'Ethos', 'Mimesis'], 'Logos, akıl yürütme, tutarlı kanıtlar, olgusal veriler ve mantıksal önermeler yoluyla ikna etmeyi ifade eder.'),
  ('Bir mesajın kaynaktan çıktıktan sonra alıcıdan hiçbir tepki beklenmeksizin yayımlandığı akşam ana haber bülteni veya sinema filmi gösterimi hangi iletişim akışına örnektir?', 'Tek yönlü ve gecikmeli geri bildirimli kitle iletişimi', ['Eşzamanlı dönüşümsel yüz yüze iletişim', 'Yatay departmanlar arası koordinasyon iletişimi', 'Simetrik kişi içi öz-değerlendirme süreci'], 'Geleneksel kitle iletişiminde ileti geniş ve heterojen bir kitleye tek yönlü ulaşır; reyting veya okuyucu mektubu gibi geri bildirimler ise dolaylı ve gecikmelidir.'),
  ('Bir yöneticinin çalışanlarına gönderdiği e-postanın sonuna \'Konuyla ilgili görüş ve önerilerinizi cuma gününe kadar yanıt olarak paylaşmanızı rica ederim\' notunu düşmesi neyi amaçlar?', 'Geri bildirim döngüsünü başlatarak iletişimi çift yönlü kılmayı', ['Anlamsal gürültüyü artırarak mesajı belirsizleştirmeyi', 'Kodaçımı sorumluluğunu yalnızca üst yönetime devretmeyi', 'Sözsüz iletişim kanallarını yazılı metnin önüne geçirmeyi'], 'Açıkça yanıt talep etmek, tek yönlü duyuruyu etkileşimsel bir iletişim sürecine dönüştürerek anlaşılırlığı ve katılımı denetlemeye yarar.'),
  ('Kütüphanede ders çalışan öğrencilerin yan masada yüksek sesle konuşan kişiye hiçbir söz söylemeden sert bir bakış atıp işaret parmağını dudaklarına götürmesi neyi gösterir?', 'Sözsüz iletişimin tek başına eksiksiz bir uyarı mesajı kodlayabildiğini', ['İletişim kurulabilmesi için mutlaka yazılı bir metne ihtiyaç duyulduğunu', 'Fiziksel gürültünün yalnızca elektronik cihazlarda meydana geldiğini', 'Kişilerarası iletişimde görsel kanalın hiçbir işlevi olmadığını'], 'Amblem niteliğindeki \'sus\' işareti ve bakış, tek bir sözcük telaffuz edilmeden mesajın kodlanıp karşı tarafça çözülmesini sağlar.'),
  ('Aşağıdaki durumlardan hangisi kodaçımı (decoding) aşamasının gerçekleştiğine doğrudan örnektir?', 'Sürücünün yol kenarındaki üçgen uyarı levhasını görüp ileride keskin viraj olduğunu anlaması', ['Grafik tasarımcının yangın çıkışı için yeni bir piktogram çizmesi', 'Yazarın roman taslağını bilgisayar klavyesiyle metin belgesine aktarması', 'Radyo vericisinin stüdyodaki sesi elektromanyetik dalgalara çevirmesi'], 'Kodaçımı, alıcının kendisine ulaşan görsel, işitsel veya yazılı simgeleri zihninde anlamlı bir mesaja dönüştürmesi sürecidir.'),
  ('Aynı mahallede büyüyen iki çocukluk arkadaşının aralarında konuşurken yarım bırakılan cümleleri bile tek bir bakışla eksiksiz tamamlaması Schramm modeline göre neyle açıklanır?', 'Ortak deneyim ve referans çerçevelerinin son derece geniş olmasıyla', ['İletişim sürecinde kanal öğesinin tamamen ortadan kalkmasıyla', 'Kamusal mesafe sınırlarının dört metrenin üzerine çıkmasıyla', 'Mesajlardaki entropi oranının yüzde yüze ulaşmasıyla'], 'Paylaşılan geçmiş ve ortak yaşantı alanı genişledikçe az sayıda simgeyle çok yoğun anlam aktarımı mümkün olur.'),
  ('Bir yolcunun otobüste yan koltuğa çantasını koyup kulaklığını takarak pencereden dışarı bakması proksemik ve sözsüz iletişim açısından nasıl yorumlanır?', 'Kişisel alan sınırını koruma ve etkileşime kapalı olduğunu bildiren savunmacı bariyer oluşturma', ['Otobüisteki diğer yolcuları grup tartışmasına davet eden düzenleyici bir jest sergileme', 'Kamusal mesafeyi mahrem mesafeye dönüştürerek yakınlık arayışına girme', 'Dil ötesi ses tonlamasıyla şoföre güzergâh değişikliği önerisinde bulunma'], 'Çanta gibi nesneleri bariyer olarak kullanmak ve göz temasını kesmek, kalabalık kamusal ortamlarda bireyin kişisel sınırını sembolik olarak koruma yöntemidir.'),
  ('Sözcüklerin sözlük anlamlarının ötesinde ses uyumu, ölçü, ritim ve imgeler aracılığıyla estetik tat uyandırmak üzere seçildiği şiir dizelerinde Jakobson\'un hangi işlevi baskındır?', 'Sanatsal / şiirsel (poetik) işlev', ['Göndergesel (betimleyici) işlev', 'Üstdil (metalinguistik) işlev', 'Kanal yoklama (fatik) işlevi'], 'İletinin kendi biçimine, ses ve söz sanatlarına odaklandığı durumlarda dilin şiirsel (poetik) işlevi ön plana çıkar.'),
  ('Hava durumu bülteninde spikerin \'Yarın sabah saatlerinde iç kesimlerde sis ve pus bekleniyor, sıcaklık sekiz derece olacak\' demesi dilin hangi işlevine örnektir?', 'Göndergesel (bilgi verici) işlev', ['Heyecana bağlı (duygusal) işlev', 'Şiirsel (estetik) işlev', 'Fatik (ilişki kurucu) işlev'], 'Dış dünyadaki olgu ve durumları nesnel, doğrulanabilir bilgi aktarımı amacıyla dile getirmek göndergesel işlevdir.'),
  ('Aşağıdakilerden hangisi sözsüz iletişimin sözlü iletişimi \'tamamlama ve pekiştirme\' işlevine uygun bir örnektir?', 'Arkadaşına \'Seni gördüğüme çok sevindim\' derken içtenlikle gülümseyip kollarını açarak sarılmak', ['Hiçbir şey söylemeden yalnızca omuz silkerek bilmediğini ifade etmek', 'Sinirli olduğu hâlde dişlerini sıkarak \'Hiç kızmadım\' demek', 'Konuşmayı bitirmek istediğinde sık sık kol saatine bakmak'], 'Söylenen olumlu sözün sıcak bir gülümseme ve sarılmayla eşzamanlı desteklenmesi, sözsüz kanalın sözel anlamı güçlendirip tamamlamasıdır.'),
  ('Etkileşimsel (interaktif) iletişim modellerini doğrusal modellerden ayıran temel özellik aşağıdakilerden hangisidir?', 'Alıcıdan kaynağa dönen geri bildirimi ve tarafların sırayla rol değiştirmesini sürece eklemesi', ['Gürültü kavramını iletişim biliminin kapsamından tamamen çıkarması', 'Yalnızca telgraf ve dumanla haberleşme gibi eski yöntemleri incelemesi', 'Kaynağın mesaj kodlama yeteneğinin doğuştan sabit olduğunu savunması'], 'Schramm gibi etkileşimsel modeller iletişimi tek yönlü ok olmaktan çıkarıp geri bildirim halkalarıyla döngüsel bir alışveriş olarak tanımlar.'),
  ('Bir uluslararası zirvede farklı ülkelerden gelen diplomatların el sıkışma sertliği, kartvizit uzatma biçimi ve selamlama mesafesi konusunda önceden bilgilendirilmesi neden önemlidir?', 'Sözsüz iletişim kodlarının kültürden kültüre değişmesi yüzünden doğabilecek yanlış anlamaları önlemek için', ['Diplomatların zirve boyunca hiç konuşmadan yalnızca işaret diliyle anlaşmasını sağlamak için', 'Basılı anlaşma metinlerinin hukuki bağlayıcılığını ortadan kaldırmak için', 'Simültane çeviri kulaklıklarındaki elektrik akımını yükseltmek için'], 'Haptik, kinesik ve proksemik normlar evrensel değil kültüreldir; bir kültürde samimiyet sayılan temas başka bir kültürde saygısızlık olarak kodaçımına uğrayabilir.'),
  ('Grup iletişiminin kitle iletişiminden ayrılan en belirgin yapısal özelliği aşağıdakilerden hangisidir?', 'Üyelerin birbirini doğrudan tanıması ve yüz yüze etkileşimle anında geri bildirim verebilmesi', ['Mesajların her zaman ulusal televizyon vericileri üzerinden dağıtılması', 'Katılımcı sayısının milyonlarla ifade edilen anonim yığınlardan oluşması', 'Grup içinde hiçbir ortak amaç veya aidiyet duygusunun bulunmaması'], 'Küçük grup iletişiminde (aile, proje ekibi, komisyon) katılımcılar sınırlı sayıdadır, ortak bir hedef etrafında doğrudan ve çift yönlü etkileşim kurarlar.'),
  ('Bir öğretmenin sınıfa girerken kürsünün arkasına saklanmak yerine sıraların arasında dolaşarak öğrencilerle göz hizasında konuşması proksemik açıdan nasıl bir etki doğurur?', 'Hiyerarşik mesafeyi azaltarak psikolojik yakınlık ve derse katılım isteğini güçlendirir', ['Sınıftaki akustik yankıyı artırarak anlamsal gürültüye neden olur', 'Öğrencilerin kodaçımı yeteneğini zayıflatarak iletişimi tek yönlüleştirir', 'Resmî yazılı iletişimi sözlü iletişimin yerine geçirir'], 'Fiziksel bariyerlerin (kürsü) kaldırılması ve mesafenin sosyal/kişisel sınıra çekilmesi iletişimde yakınlık (immediacy) algısı yaratarak etkileşimi artırır.'),
  ('İletişim sürecinde \'bağlam\' (context) kavramının mesajın anlamlandırılmasındaki rolünü en iyi açıklayan ifade hangisidir?', 'İletişimin gerçekleştiği fiziksel ortam, toplumsal ilişki, zaman ve kültürel iklimin sözcüklere özgül anlam kazandırması', ['Mesajın kaç kelimeden oluştuğunu sayan istatistiksel veri tablosu olması', 'Yalnızca radyo vericisinin megahertz cinsinden yayın frekansını göstermesi', 'Alıcının işitme duyusunun desibel eşiğini ölçen tıbbi cihaz olması'], 'Hiçbir ileti boşlukta var olmaz; aynı cümle bir tiyatro sahnesinde, bir mahkeme salonunda veya bir arkadaş sohbetinde bağlama göre bambaşka anlamlar kazanır.'),
  ('Thomas Gordon\'un etkili iletişim yaklaşımına göre \'Sen dili\' yerine \'Ben dili\' kullanmanın kişilerarası ilişkilerdeki en önemli katkısı nedir?', 'Karşı tarafı suçlayıp savunmaya itmeden konuşmacının kendi duygusunu ve somut etkiyi paylaşması', ['Tartışmayı tek taraflı biçimde sonlandırarak muhatabın söz hakkını elinden alması ve otoriteyi pekiştirmesi', 'Sorunun kaynağını tamamen dışsal koşullara bağlayarak bireysel sorumluluk duygusunu ortadan kaldırması', 'Duygusal ifadeleri bütünüyle gizleyip yalnızca resmî tutanak üslubuyla mesafeli konuşmayı sağlaması'], 'Ben dili, kişiliğe yönelik yargılama içermez; davranışı, bu davranışın yarattığı somut sonucu ve konuşmacıda uyandırdığı duyguyu dürüstçe aktararak savunmacılığı azaltır.'),
  ('Randevusuna kırk dakika geç gelen arkadaşına bir kişinin aşağıdakilerden hangisini söylemesi \'Ben dili\' kalıbına uygun bir örnektir?', 'Haber vermeden geciktiğinde başına bir iş geldiğini düşünerek endişeleniyorum ve planımız aksıyor', ['Her zamanki gibi yine çok sorumsuz davranıyorsun ve kimsenin vaktine zerre kadar saygı duymuyorsun', 'Sen zaten hayatın boyunca hiçbir sözünü zamanında tutmayı başaramayan bencil bir insansın', 'Bir daha seninle herhangi bir yere gitmeyi kesinlikle düşünmüyorum çünkü çok düşüncesizsin'], 'Doğru seçenekte kişilik hakareti yapılmadan somut davranış (haber vermeden gecikmek), somut etki (planın aksaması) ve duygu (endişelenmek) birlikte ifade edilmiştir.'),
  ('Dinleyicinin karşı tarafı anlamak için değil, konuşmacının cümlelerindeki en ufak bir çelişkiyi yakalayıp onu alt etmek amacıyla pusu kurarak dinlemesi nasıl adlandırılır?', 'Tuzak kurucu dinleme', ['Kapsamlı dinleme', 'Yansıtmacı dinleme', 'Geliştirici dinleme'], 'Tuzak kurucu dinlemede alıcı sessizce bekler ancak amacı anlamak değil, konuşmacının eski sözleriyle çelişen bir açığını bulup saldırıya geçmektir.'),
  ('Konuşmacının yüzüne bakıp başını sallayarak onu dinliyormuş izlenimi verdiği hâlde zihninde akşam ne yemek pişireceğini planlayan bir kişi hangi dinleme türünü sergilemektedir?', 'Görünüşte dinleme', ['Seçici dinleme', 'Savunmacı dinleme', 'Eleştirel dinleme'], 'Görünüşte (sahte) dinlemede beden dili onay sinyalleri verse de zihin tamamen başka düşüncelerle meşguldür ve işitilenler anlamlandırılmaz.'),
  ('Karşısındaki kişinin niyetini hiç sormadan \'Bana bilerek selam vermedi, kesin beni küçümsüyor\' biçiminde kesin hükme varmak hangi bilişsel ve iletişimsel çarpıtmadır?', 'Akıl okuma', ['Etkin özetleme', 'Sokratik sorgulama', 'Bilişsel esneklik'], 'Akıl okuma, somut veri veya açık doğrulama olmaksızın karşı tarafın ne düşündüğünü ya da hangi gizli niyetle davrandığını bildiğini varsayma engelidir.'),
  ('Bir fabrikada üretim müdürü ile pazarlama müdürünün yeni ürün lansman takvimini uyumlu hâle getirmek üzere kendi aralarında yaptıkları toplantı örgütsel iletişimin hangi yönüne örnektir?', 'Yatay iletişim', ['Yukarıdan aşağıya dikey iletişim', 'Aşağıdan yukarıya dikey iletişim', 'Dışsal kamusal iletişim'], 'Örgüt şemasında aynı hiyerarşik basamakta yer alan eş düzey birim yöneticileri veya çalışanlar arasındaki eşgüdüm amaçlı bilgi alışverişi yatay iletişimdir.'),
  ('Şirket genel müdürlüğünün vardiya saatlerindeki değişikliği tüm birimlere iç genelge ile duyurması nasıl bir örgütsel iletişim akışıdır?', 'Yukarıdan aşağıya dikey iletişim', ['Aşağıdan yukarıya dikey iletişim', 'Yatay meslektaş iletişimi', 'Biçimsel olmayan söylenti ağı'], 'Üst yönetim kademesinden alt kademelere doğru emir, yönerge, görev tanımı ve politika aktarımı yukarıdan aşağıya dikey iletişimi oluşturur.'),
  ('Montaj hattındaki işçilerin makine arızalarına ilişkin öneri formlarını ve memnuniyet anketlerini fabrika yönetimine iletmesi hangi örgütsel iletişim yönünü temsil eder?', 'Aşağıdan yukarıya dikey iletişim', ['Yukarıdan aşağıya emir-komuta iletişimi', 'Eş kademeli yatay koordinasyon', 'Kurum dışı lobicilik faaliyeti'], 'Astlardan üstlere doğru rapor, dilekçe, şikâyet, öneri ve saha geri bildirimi ulaştırılması aşağıdan yukarıya dikey iletişimdir.'),
  ('Bir gıda firmasının ürettiği kavanozlarda cam kırığı şüphesi belirdiğinde kriz iletişimi ilkelerine göre atması gereken en doğru ilk adım nedir?', 'Vakit kaybetmeden şeffaf bir açıklama yaparak ilgili parti ürünleri geri çağırmak ve tüketici sağlığını öncelemek', ['Haberin sosyal medyada unutulmasını bekleyerek haftalarca tam sessizliğe bürünmek ve yorumları silmek', 'Suçu rakip firmaların komplosuna atarak kanıt sunmadan sert bir karşı reklam kampanyası başlatmak', 'Sorunu dile getiren tüketicilere derhal tazminat davası açılacağını duyuran tehditkâr bir bülten yayımlamak'], 'Kriz iletişiminde \'altın saatler\' içinde hızlı, dürüst, empatik ve sorumluluk alan bir bilgilendirme yapmak kurumsal itibarı yıkımdan koruyan en temel kuraldır.'),
  ('Kişinin başkasının haklarını çiğnemeden kendi duygu, düşünce ve sınırlarını dürüstçe ifade edebilmesi, gerektiğinde suçluluk duymadan \'hayır\' diyebilmesi hangi iletişim tarzıdır?', 'Girişken (güvengen / atılgan) davranış', ['Saldırgan (agresif) davranış', 'Çekingen (pasif) davranış', 'Pasif-agresif (dolaylı saldırgan) davranış'], 'Girişkenlik (assertiveness), ne kendi hakkından vazgeçen çekingenliği ne de başkasını ezen saldırganlığı içerir; özsaygı ve karşılıklı saygı dengesine dayanır.'),
  ('Toplantıda verilen ek göreve yüz yüze itiraz edemediği hâlde işi kasten yavaşlatan, dosyaları \'unutan\' ve arkadan söylenen bir çalışanın sergilediği iletişim tutumu hangisidir?', 'Pasif-agresif davranış', ['Girişken ve saydam davranış', 'Yapıcı problem çözme tutumu', 'Empatik etkin dinleme'], 'Öfkeyi veya itirazı doğrudan ve sağlıklı biçimde dile getirmek yerine erteleme, küskünlük, iğneleme ve örtük sabotajla dışavurma pasif-agresif iletişim kalıbıdır.'),
  ('Bir kurumun logosu, kurumsal renk paleti, yazı karakteri, antetli kâğıtları, mimari tasarımı ve çalışan üniformaları gibi kendini dış dünyaya tanıttığı somut göstergeler bütünü neyi oluşturur?', 'Kurumsal kimlik', ['Biçimsel olmayan söylenti ağı', 'Kişilerarası empatik yansıtma', 'Kamuoyu suskunluk sarmalı'], 'Kurumsal kimlik, bir örgütün \'biz kimiz\' sorusuna görsel, sözel ve davranışsal standartlarla verdiği planlı ve ayırt edici temsil sistemidir.'),
  ('Bir şirketin ürettiği ürünün doğrudan reklamını yapmak yerine gençlik senfoni orkestrasının Anadolu turnesi masraflarını üstlenerek toplum nezdinde sempati ve saygınlık kazanmayı amaçlaması hangi halkla ilişkiler uygulamasıdır?', 'Kültür-sanat sponsorluğu', ['Kriz dönemi tekzip yayını', 'Kurum içi dikey denetim', 'Doğrudan sıcak satış pazarlaması'], 'Sponsorluk, kurumun doğrudan ticari faaliyet alanı dışındaki spor, sanat, çevre veya eğitim etkinliklerine maddi/ayni destek vererek kurumsal imaj ve itibarını güçlendirmesidir.'),
  ('Bir konuşmacının söylediklerini değerlendirirken içerikten ziyade konuşmacının memleketine, şivesine veya etnik kökenine bakarak baştan olumsuz hüküm vermek hangi iletişim engelidir?', 'Kalıpyargı (stereotip) ve önyargı süzgeci', ['Fizyolojik işitme kaybı', 'Teknolojik bant genişliği darlığı', 'Yansıtmacı empatik doğrulama'], 'Belirli toplumsal gruplara yönelik katı genellemeler (kalıpyargılar) ve bunlara eşlik eden duygusal peşin hükümler (önyargılar) mesajın nesnel biçimde dinlenmesini engeller.'),
  ('Bir yöneticinin çalışanına yapıcı eleştiri sunarken önce takdir ettiği güçlü bir yönünü belirtmesi, ardından geliştirilmesi gereken somut noktayı açıklaması ve konuşmayı güven ifadesiyle bitirmesi hangi geri bildirim yöntemiyle anılır?', 'Sandviç tekniği', ['Sقراطik çürütme tekniği', 'Şok ve yıldırma tekniği', 'Tek yönlü ültimatom tekniği'], 'Sandviç geri bildirim yöntemi, savunmacı direnci azaltmak amacıyla gelişime açık eleştiriyi iki samimi olumlu değerlendirmenin arasına yerleştirmeyi öngörür.'),
  ('Kurum içinde çalışanların \'Biz burada işleri böyle yaparız\' diyerek kuşaktan kuşağa aktardıkları ortak değerler, normlar, kahraman öyküleri, törenler ve yazısız alışkanlıklar bütünü hangi kavramla tanımlanır?', 'Örgüt (kurum) kültürü', ['Pazarlama karması', 'Medya planlama çizelgesi', 'Reklamveren medya payı'], 'Edgar Schein ve Geert Hofstede gibi kuramcıların incelediği örgüt kültürü, kurum üyelerinin paylaştığı temel varsayımlar, semboller ve davranış kalıpları sistemidir.'),
  ('İş görüşmesinde veya müzakerede açık uçlu soruların (\'Bu projedeki en büyük güçlüğü nasıl aştınız?\') kapalı uçlu sorulara (\'Projeyi bitirdiniz mi?\') kıyasla sağladığı iletişimsel üstünlük nedir?', 'Muhatabı tek kelimelik \'evet/hayır\' yanıtlarının ötesine taşıyarak ayrıntılı düşünce ve deneyim paylaşımına teşvik etmesi', ['Görüşme süresini birkaç saniyeye indirerek adayın konuşmasını tamamen engellemesi', 'Dinleyicinin hiçbir not tutmasına veya dikkat göstermesine gerek bırakmaması', 'Yalnızca matematiksel istatistik kodlaması için ikili sayı sistemi üretmesi'], 'Açık uçlu sorular (nasıl, neden, neler hissettiniz vb.) karşı tarafa anlatım alanı açar, diyaloğu derinleştirir ve zengin bağlamsal bilgi sağlar.'),
  ('Bir kurumun yalnızca hissedarlarına kâr dağıtmakla yetinmeyip çevre kirliliğini azaltma, kız çocuklarının eğitimine burs sağlama ve iş güvenliğini geliştirme projelerini gönüllü biçimde yürütmesi hangi kavramla ifade edilir?', 'Kurumsal sosyal sorumluluk', ['Doğrudan satış promosyonu', 'Asimetrik lobicilik', 'Eşik bekçiliği denetimi'], 'Kurumsal sosyal sorumluluk (KSS), işletmelerin ekonomik ve yasal yükümlülüklerinin ötesine geçerek toplumsal refaha ve sürdürülebilir çevreye etik katkılar sunmasıdır.'),
  ('Dinleyicinin uzun bir konuşmanın içinden yalnızca kendi mevcut inançlarını doğrulayan veya kendi çıkarına dokunan cümleleri cımbızlayıp geri kalanını duymazdan gelmesi hangi dinleme türüdür?', 'Seçici dinleme', ['Empatik dinleme', 'Görünüşte dinleme', 'Bütüncül dinleme'], 'Seçici dinlemede alıcı tüm mesaj akışına değil, yalnızca kendi ilgi alanına, beklentisine ya da önyargısına uyan belirli parçalara kulak verir.'),
  ('Söylenen her sıradan cümleyi kendi kişiliğine yönelik bir eleştiri veya suçlama gibi algılayıp anında karşı saldırıya ya da mazeret üretmeye geçen kişi nasıl bir dinleme alışkanlığına sahiptir?', 'Savunmacı dinleme', ['Takdir edici dinleme', 'Çözümleyici dinleme', 'Yaratıcı dinleme'], 'Savunmacı dinlemede birey güvensizlik veya tehdit algısı nedeniyle masum soruları bile iğneleme sayarak iletişimi çatışmaya dönüştürür.'),
  ('Kurumsal halkla ilişkilerde \'kurum içi hedef kitle\' (internal publics) kapsamına aşağıdakilerden hangisi doğrudan girer?', 'İşletmenin mavi ve beyaz yakalı çalışanları, yöneticileri ile çalışan aileleri', ['Ulusal televizyon kanallarının ekonomi servisi muhabirleri', 'Ürünü ilk kez market rafında gören potansiyel tüketiciler', 'Sektörü denetleyen bağımsız bakanlık müfettişleri'], 'Halkla ilişkiler dış kamulara yönelmeden önce kurumun ilk elçileri olan kendi çalışanlarını, yöneticilerini ve iç paydaşlarını kapsayan kurum içi iletişimi sağlam kurmalıdır.'),
  ('İki meslektaşın nöbet çizelgesi konusunda anlaşmazlığa düştüğünde her ikisinin de kendi ilk talebinden bir miktar feragat ederek orta noktada buluşması hangi çatışma çözme yaklaşımıdır?', 'Uzlaşma (ödünleşim / orta yol bulma)', ['Hükmetme (zorlama)', 'Boyun eğme (uyma)', 'Yok sayma (inkâr)'], 'Uzlaşma (compromising) stilinde taraflar \'biraz sen vazgeç, biraz ben vazgeçeyim\' mantığıyla karşılıklı fedakârlık yaparak kabul edilebilir bir ara formülde anlaşırlar.'),
  ('Aşırı bilgi yüklemesi (information overload) yaşanan bir kurumsal ortamda çalışanların e-posta kutularına günde yüzlerce gereksiz bildirim düşmesinin doğuracağı en olası iletişimsel sonuç nedir?', 'Kritik önemdeki mesajların gözden kaçması ve karar alma kalitesinin düşmesi', ['Tüm çalışanların her belgeyi satır satır ezberleyerek sıfır hatayla çalışması', 'Birimler arasındaki anlamsal ve psikolojik gürültünün kendiliğinden yok olması', 'Yüz yüze empatik dinleme süresinin kendiliğinden üç katına çıkması'], 'İletinin miktarı alıcının bilişsel işleme kapasitesini aştığında (aşırı bilgi yükü) dikkat dağılır, önceliklendirme bozulur ve önemli uyarılar sıradan iletiler arasında kaybolur.'),
  ('Kurumsal iletişimde çalışanların kuruma duyduğu aidiyeti güçlendiren, işletmenin gelecekte ulaşmak istediği ideal konumu tanımlayan \'vizyon\' ile varoluş amacını açıklayan \'misyon\' arasındaki fark nedir?', 'Misyon kurumun bugünkü temel görev ve varlık nedenini, vizyon ise uzun vadede kavuşmayı hedeflediği gelecek ufkunu belirtir', ['Misyon yalnızca muhasebe departmanının vergi borçlarını, vizyon ise yalnızca güvenlik görevlilerinin nöbet listesini kapsar', 'Misyon her hafta değiştirilen reklam sloganını, vizyon ise şirketin kuruluş yılındaki bina adresini gösterir', 'Misyon rakipleri kötüleyen gizli belgeleri, vizyon ise mahkemelere sunulan savunma dilekçelerini ifade eder'], 'Stratejik kurumsal iletişimde misyon \'Neden varız, ne üretiyoruz ve kime hizmet ediyoruz?\' sorusunu yanıtlarken; vizyon \'Gelecekte nerede olmak istiyoruz?\' idealini çizer.'),
  ('Sağlık iletişiminde hekimin hastanın sözünü ilk on sekiz saniyede kesmeyip onu empatik biçimde dinlemesinin klinik sürece sağladığı en önemli katkı nedir?', 'Hastanın gerçek yakınmalarını eksiksiz paylaşmasını sağlayarak doğru tanı olasılığını ve tedaviye uyumu yükseltmesi', ['Tıbbi laboratuvar tahlillerine ve görüntüleme cihazlarına duyulan ihtiyacı tamamen ortadan kaldırması', 'Muayene süresini üç saate çıkararak hastanedeki tüm randevu sistemini durdurması', 'Hastanın kendi reçetesini hekim onayı olmadan yazmasına yasal yetki tanıması'], 'Hasta-hekim iletişimi araştırmaları, etkin dinleme ve hasta merkezli iletişimin hem tanı isabetini hem de hastanın ilaç tedavisini düzenli sürdürme oranını belirgin biçimde artırdığını kanıtlamıştır.'),
  ('Kurumsal halkla ilişkilerde basın bülteni hazırlanırken en önemli ve çarpıcı bilginin ilk paragrafta (5N1K), ayrıntıların ise önem sırasına göre azalarak alt paragraflarda verilmesi hangi yazım tekniğidir?', 'Ters piramit tekniği', ['Bilinç akışı tekniği', 'Sarmal gizem tekniği', 'Kapalı zarf tekniği'], 'Gazetecilik ve halkla ilişkiler bültenlerinde editörlerin metni sondan kısaltabilmesine olanak tanıyan ve ana haberi en başa koyan yapı ters piramit tekniğidir.'),
  ('Bir tartışmada \'Beni hiç dinlemiyorsun!\' diye bağıran eşine karşı tarafın sakin bir sesle \'Şu an söylediklerime yeterince dikkat vermediğimi düşündüğün için kırgın ve kızgınsın; elimdeki telefonu bırakıyorum, seni dinliyorum\' demesi neyin örneğidir?', 'Duyguyu doğrulayan etkin dinleme ve yapıcı yatıştırma tepkisinin', ['Sorunu görmezden gelen pasif kaçınma ve küskünlük davranışının', 'Üstünlük taslayan Eleştirel Ebeveyn benlik durumu müdahalesinin', 'Tuzak kurucu dinlemeyle karşı tarafın açığını yakalama çabasının'], 'Savunmaya geçip \'Hayır dinliyorum!\' diye tartışmak yerine karşı tarafın duygusunu yansıtıp somut dikkat eylemi (telefonu bırakmak) göstermek gerilimi hızla düşürür.'),
  ('Bir şirketin iç iletişim birimi tarafından aylık çıkarılan personel dergisi, kurum içi portal duyuruları ve oryantasyon el kitapları öncelikle hangi amaca hizmet eder?', 'Kurum kültürünü paylaşmak, aidiyeti pekiştirmek ve bölümler arası bilgi bütünlüğü sağlamak', ['Yabancı borsalardaki spekülatif hisse senedi fiyatlarını anlık olarak belirlemek', 'Rakip şirketlerin üretim tesislerindeki ticari sırları gizlice ele geçirmek', 'Tüketicilerin market raflarındaki anlık dürtüsel satın alma kararlarını yönetmek'], 'Kurum içi iletişim araçları çalışanların ortak hedefler etrafında kenetlenmesini, belirsizliğin azalmasını ve kurumsal değerlerin içselleştirilmesini sağlar.'),
  ('Bir ekip toplantısında sessiz kalan üyelere toplantı yöneticisinin \'Ayşe Hanım, saha deneyiminiz açısından bu taslakta gözümüzden kaçan bir risk görüyor musunuz?\' diye sorması hangi iletişimsel liderlik becerisidir?', 'Kapsayıcı kolaylaştırıcılık ve katılımcı geri bildirim daveti', ['Otoriter tek seslilik ve grup düşüncesi dayatması', 'Kişilik etiketlemesi yoluyla savunmacı iklim yaratma', 'Bilgi saklayarak asimetrik güç üstünlüğü kurma'], 'Toplantılarda baskın konuşmacıların yanı sıra çekingen veya gözlemci üyelerin uzmanlığına saygılı biçimde alan açmak karar kalitesini artıran kolaylaştırıcı (facilitative) iletişimdir.'),
  ('Medyanın insanlara "ne düşüneceğini" değil, "ne hakkında düşüneceğini" söylemede başarılı olduğunu savunan kuram hangisidir?', 'Gündem Belirleme Kuramı', ['Kullanımlar ve Doyumlar Yaklaşımı', 'İki Aşamalı Akış Modeli', 'Bilişsel Uyumsuzluk Kuramı'], 'Maxwell McCombs ve Donald Shaw tarafından geliştirilen Gündem Belirleme Kuramı, medyanın konuları öne çıkararak kamuoyu gündemini şekillendirdiğini vurgular.'),
  ('Haber kaynaklarından gelen sayısız bilgi arasından hangilerinin bültene gireceğine ve hangilerinin eleneceğine karar veren editöryal süzgeç sürecine ne ad verilir?', 'Eşik Bekçiliği', ['Yankı Odası', 'Gündem Belirleme', 'Suskunluk Sarmalı'], 'Kurt Lewin\'in ortaya attığı ve David Manning White\'ın haberciliğe uyarladığı eşik bekçiliği (gatekeeping), haber akışındaki kontrol noktalarını ifade eder.'),
  ('Bireylerin toplumda dışlanma korkusu nedeniyle azınlıkta kaldığını düşündükleri fikirlerini gizleyip baskın görüşe uyum sağlamasını açıklayan kuram hangisidir?', 'Suskunluk Sarmalı', ['Gündem Belirleme', 'Ekme Kuramı', 'Kullanımlar ve Doyumlar'], 'Elisabeth Noelle-Neumann\'ın Suskunluk Sarmalı kuramına göre bireyler dışlanma korkusuyla kamuoyu iklimini tarar ve görüşleri azınlıktaysa susmayı tercih eder.'),
  ('Televizyonu yoğun izleyen bireylerin dünyayı gerçekte olduğundan çok daha tehlikeli ve şiddet dolu bir yer olarak algılamasını açıklayan kuram hangisidir?', 'Ekme Kuramı', ['Çerçeveleme Kuramı', 'Bilgi Gediği Kuramı', 'Gündem Belirleme Kuramı'], 'George Gerbner\'in Ekme (Kültivasyon) Kuramı, uzun süreli ve yoğun televizyon izlemenin bireylerin toplumsal gerçeklik algısını televizyon dünyasına benzettiğini savunur.'),
  ('1922 yılında yayımladığı "Kamuoyu" (Public Opinion) adlı eseriyle insanların dış dünyayı zihinlerindeki "resimler" ve "stereotipler" aracılığıyla tanıdığını belirten düşünür kimdir?', 'Walter Lippmann', ['Harold Lasswell', 'Edward Bernays', 'John Dewey'], 'Gazeteci ve kuramcı Walter Lippmann, "Public Opinion" kitabında medyanın dış dünya ile zihnimizdeki resimler (sahte çevre) arasında köprü kurduğunu savunmuştur.'),
  ('Kitle iletişim araçlarından yayılan mesajların izleyiciyi anında ve doğrudan etkilediğini savunan erken dönem medya yaklaşımı aşağıdakilerden hangisidir?', 'Sihirli Mermi', ['Kullanımlar ve Doyumlar', 'Alımlama Analizi', 'İki Aşamalı Akış'], 'İki dünya savaşı arası dönemde etkili olan Sihirli Mermi (veya Hipodermik İğne) modeli, izleyiciyi pasif ve savunmasız kabul ederek medyanın mutlak gücüne inanmıştır.'),
  ('İki Aşamalı Akış Kuramına göre medya mesajlarını yakından takip edip yorumlayarak kendi sosyal çevresindeki insanlara aktaran etkili kişilere ne ad verilir?', 'Kanaat önderi', ['Eşik bekçisi', 'Haber ombudsmanı', 'Medya okuryazarı'], 'Elihu Katz ve Paul Lazarsfeld\'in geliştirdiği modelde, kitle iletişiminden gelen iletileri süzüp kişilerarası iletişimle çevrelerine yayan bireylere kanaat önderi denir.'),
  ('Jürgen Habermas\'ın yurttaşların devlet baskısından ve ticari çıkarlardan bağımsız biçimde rasyonel tartışma yürüterek kamuoyu oluşturduğu alanı tanımlamak için kullandığı kavram nedir?', 'Kamusal Alan', ['Kültür Endüstrisi', 'Küresel Köy', 'Simülasyon Evreni'], 'Habermas, "Kamusal Alanın Yapısal Dönüşümü" eserinde 18. yüzyıl kahvehaneleri ve basın kulüplerinde gelişen eleştirel-rasyonel tartışma ortamını kamusal alan olarak kavramsallaştırmıştır.'),
  ('Stuart Hall\'un "Kodlama ve Kodaçımı" (Encoding/Decoding) modelinde, izleyicinin haberdeki egemen mesajı hiçbir itiraz geliştirmeden üreticinin istediği anlamıyla kabul etmesine ne denir?', 'Egemen-hegemonik okuma', ['Müzakereci okuma', 'Muhalif (karşıt) okuma', 'Yapıbozumcu okuma'], 'Stuart Hall izleyici okumalarını üçe ayırır: Mesajı olduğu gibi benimseyen egemen okuma, kısmen kabul edip yerel koşullara göre esneten müzakereci okuma ve tamamen reddeden muhalif okuma.'),
  ('İzleyicinin yalnızca kendi siyasi veya kültürel inançlarıyla örtüşen haber kanallarını izlemeyi tercih etmesi iletişim psikolojisinde hangi kavramla adlandırılır?', 'Seçici maruz kalma', ['Öne çıkarma etkisi', 'Anaakımlaştırma', 'Yarı-istatistiksel algı'], 'Seçici maruz kalma (selective exposure), kişinin bilişsel çelişki yaşamamak adına kendi ön kabulleriyle uyumlu bilgi kaynaklarına yönelip karşıt kaynaklardan uzak durmasıdır.'),
  ('Gazetecilik etiğinde bir haber metni yazılırken kitleye eksiksiz bilgi vermek için yanıtlanması gereken temel sorular bütününe ne ad verilir?', '5N 1K kuralı', ['Ters piramit tekniği', 'Eşik bekçiliği ilkesi', 'Çift kaynak doğrulaması'], 'Habercilikte "Ne, Nerede, Ne zaman, Nasıl, Neden ve Kim" sorularını kapsayan 5N 1K kuralı, olayın temel unsurlarının eksiksiz aktarılmasını sağlar.'),
  ('Demokratik rejimlerde yasama, yürütme ve yargı erklerini kamu adına denetleme işlevi üstlenmesi nedeniyle basına verilen geleneksel unvan nedir?', 'Dördüncü Güç', ['Sessiz Çoğunluk', 'Resmî Gazete', 'Kamu Denetçisi'], '18. yüzyıldan itibaren Edmund Burke ve Thomas Carlyle gibi isimlerle anılan "Dördüncü Güç" (Fourth Estate) kavramı, basının siyasi iktidarı denetleyen bağımsız bir erk olmasını ifade eder.'),
  ('Marshall McLuhan\'ın iletişim teknolojilerinin içeriğinden ziyade bizzat aracın kendisinin insan algısını ve toplumsal örgütlenmeyi dönüştürdüğünü özetleyen ünlü sözü hangisidir?', 'Araç mesajdır', ['Bilgi güçtür', 'Rıza imal edilir', 'Gündem politikadır'], 'Kanadalı iletişim kuramcısı Marshall McLuhan, "The medium is the message" (Araç mesajdır) sözüyle matbaadan televizyona kullanılan teknolojinin insan duyularını ve toplumu biçimlendirdiğini vurgulamıştır.'),
  ('Haber bültenlerinin ciddi kamusal tartışmalar yerine magazinleştirilmiş, dramatize edilmiş ve eğlence unsurlarıyla harmanlanmış içerikler sunmasını karşılayan kavram hangisidir?', 'Haber-eğlence', ['Yurttaş gazeteciliği', 'Veri gazeteciliği', 'Kamu yayıncılığı'], '"Information" (bilgi/haber) ve "entertainment" (eğlence) kelimelerinin birleşiminden doğan infotainment, reyting kaygısıyla haberin ciddi bağlamından koparılıp şova dönüştürülmesidir.'),
  ('Televizyon, radyo ve basılı gazete gibi tek yönlü iletişime dayalı kitle iletişim araçlarını dijital ve etkileşimli araçlardan ayırmak için kullanılan genel kavram nedir?', 'Geleneksel (konvansiyonel) medya', ['Sosyal ağ medyası', 'Algoritmik medya', 'Merkeziyetsiz medya'], 'Matbaa, radyo, televizyon ve sinema gibi Web öncesi döneme ait, merkezden kitleye tek yönlü yayın yapan mecralar geleneksel (konvansiyonel) medya olarak adlandırılır.'),
  ('Toplumun tamamına soru sormak yerine, toplumun demografik ve sosyolojik özelliklerini matematiksel olasılıkla yansıtan küçük bir grubun görüşünü ölçme yöntemine ne denir?', 'Temsili örnekleme', ['Tam sayım envanteri', 'Odak grup mülakatı', 'İçerik çözümlemesi'], 'George Gallup\'un 1936 seçimlerini küçük ama bilimsel kotalı bir grupla doğru tahmin etmesiyle yaygınlaşan temsili örnekleme, kamuoyu yoklamalarının temel istatistiksel yöntemidir.'),
  ('Gazete veya televizyon kuruluşlarında okur ve izleyicilerin haberlerle ilgili şikâyetlerini inceleyip meslek ilkeleri doğrultusunda özdenetim yapan bağımsız temsilciye ne ad verilir?', 'Okur temsilcisi', ['Genel yayın yönetmeni', 'İstihbarat şefi', 'Sorumlu yazı işleri müdürü'], 'Medya ombudsmanı (okur/izleyici temsilcisi), yayın kuruluşu ile kamu arasındaki güveni korumak için hataları, etik ihlalleri ve okur eleştirilerini bağımsız gözle değerlendirir.'),
  ('Arama motorları ve sosyal medya algoritmalarının kullanıcının geçmiş tıklamalarına göre yalnızca seveceği içerikleri gösterip onu farklı görüşlerden yalıtmasına ne ad verilir?', 'Filtre balonu', ['Suskunluk sarmalı', 'Bilgi gediği', 'Medya yöndeşmesi'], 'İnternet aktivisti Eli Pariser\'in kavramsallaştırdığı filtre balonu (filter bubble), kişiselleştirme algoritmalarının bireyi kendi zevk ve görüşlerinden oluşan görünmez bir fanusa hapsetmesidir.'),
  ('Sosyal ağlarda bireylerin yalnızca kendileriyle aynı siyasi ve kültürel görüşü paylaşan kişilerle etkileşime girerek kendi inançlarının sürekli yankılanıp pekiştiği ortama ne denir?', 'Yankı odası (Echo chamber)', ['Kamusal alan (Public sphere)', 'Açık kaynak (Open source)', 'Haber merkezi (Newsroom)'], 'Yankı odası, karşıt seslerin dışlandığı ve benzer düşünen insanların birbirlerinin iddialarını sürekli tekrarlayıp doğrulayarak kutuplaşmayı artırdığı kapalı iletişim ağlarıdır.'),
  ('Ses, görüntü, metin ve veri gibi farklı iletişim biçimlerinin sayısallaşma sayesinde tek bir cihazda veya ağda birleşmesi sürecine ne ad verilir?', 'Yöndeşme', ['Kültürel ekme', 'Anaakımlaştırma', 'Çerçeveleme'], 'Medya yöndeşmesi (convergence), geleneksel olarak ayrı olan telekomünikasyon, yayıncılık ve bilişim teknolojilerinin dijital tabanda bütünleşmesini ifade eder.'),
  ('Dijital medyada izleyicinin yalnızca içerik tüketen pasif bir alıcı olmaktan çıkıp aynı zamanda içerik üreten, yorumlayan ve paylaşan aktif bir özneye dönüşmesini karşılayan kavram nedir?', 'Üretüketici (Prosumer)', ['Eşik bekçisi (Gatekeeper)', 'Medya ombudsmanı', 'Kanaat önderi'], 'Alvin Toffler\'ın ortaya attığı "prosumer" (producer + consumer / üreten tüketici) kavramı, Web 2.0 ile birlikte kullanıcıların hem içerik üreticisi hem tüketicisi olmasını açıklar.'),
  ('Yanlış olduğu bilindiği halde insanları kandırmak, kamuoyunu yönlendirmek veya zarar vermek amacıyla kasıtlı olarak üretilip yayılan uydurma bilgilere ne ad verilir?', 'Dezenformasyon', ['Mezenformasyon', 'Malenformasyon', 'Enformasyon'], 'Dezenformasyonda temel ayırt edici ölçüt "bilginin yanlış olması" ve "zarar verme / aldatma kastının bulunması"dır.'),
  ('Doğru olduğuna içtenlikle inanılarak, herhangi bir zarar verme veya kandırma kastı olmaksızın iyi niyetle paylaşılan yanlış ya da hatalı bilgilere ne ad verilir?', 'Mezenformasyon', ['Dezenformasyon', 'Malenformasyon', 'Manipülasyon'], 'Mezenformasyon (misinformation), örneğin bir aile WhatsApp grubunda şifa sağladığı sanılarak paylaşılan ama tıbben yanlış olan bilgide olduğu gibi kasıtsız yayılan yanlış bilgidir.'),
  ('Yapay zekâ ve derin öğrenme algoritmaları kullanılarak bir kişinin yüzünün veya sesinin gerçekte hiç söylemediği sözleri söylüyormuş gibi videoya sentezlenmesine ne ad verilir?', 'Deepfake (Derin sahtecilik)', ['Clickbait (Tık tuzağı)', 'Gatekeeping (Eşik bekçiliği)', 'Crowdsourcing (Kitle kaynak)'], '"Deep learning" (derin öğrenme) ve "fake" (sahte) kelimelerinden türetilen deepfake, üretken çekişmeli ağlar (GAN) yardımıyla yüksek gerçeklikte sahte görsel-işitsel medya üretilmesidir.'),
  ('Sosyal medya platformlarında gerçek kullanıcı gibi davranmak üzere programlanmış, otomatik olarak beğeni, paylaşım ve yorum üreterek yapay gündem oluşturan yazılımlara ne ad verilir?', 'Sosyal bot', ['Yurttaş gazeteci', 'Doğrulama uzmanı', 'Dijital göçebe'], 'Sosyal botlar (ve bunların oluşturduğu botnet ağları), belirli etiketleri yapay olarak trend listesine sokmak veya muhalif sesleri gürültüyle bastırmak için kullanılan otomatik yazılımlardır.'),
  ('Yayılıp kamuoyunda etkili olmaya başlamış bir sahte haberin veya yanlış iddianın, olgusal kanıtlar ve belgeler sunularak sonradan yanlışlanıp çürütülmesi işlemine ne ad verilir?', 'Çürütme / Doğrulama (Debunking)', ['Ön-çürütme (Prebunking)', 'Çerçeveleme (Framing)', 'Kişiselleştirme (Personalization)'], '"Debunking", dolaşıma girmiş yanlış iddiaların doğruluk kontrolü (fact-checking) platformları tarafından geriye dönük kanıt incelemesiyle çürütülmesidir.'),
  ('İnsanların mevcut inançlarını doğrulayan kanıtları hemen kabul edip bu inançlarla çelişen güvenilir kanıtları görmezden gelme veya küçümseme eğilimine ne ad verilir?', 'Doğrulama yanlılığı (Confirmation bias)', ['Bulunabilirlik kısayolu (Availability heuristic)', 'Çıpalama yanılgısı (Anchoring bias)', 'Batık maliyet yanılgısı (Sunk cost fallacy)'], 'Doğrulama yanlılığı (teyit önyargısı), sosyal medyada kullanıcıların kendi dünya görüşlerine uyan sahte haberleri hiç sorgulamadan hızla paylaşmasının arkasındaki en güçlü bilişsel yanlılıktır.'),
  ('Profesyonel gazetecilik eğitimi veya kurumsal basın kartı olmayan sıradan yurttaşların, tanık oldukları olayları cep telefonu ve sosyal medya aracılığıyla haberleştirip paylaşmasına ne ad verilir?', 'Yurttaş gazeteciliği', ['Sarı gazetecilik', 'İliştirilmiş gazetecilik', 'Ajans gazeteciliği'], 'Yurttaş gazeteciliği (citizen journalism), geleneksel medyanın ulaşamadığı veya görmezden geldiği anlık olayların bizzat olay yerindeki vatandaşlar tarafından kaydedilip kamusallaştırılmasıdır.'),
  ('Bireylerin çeşitli medya türlerindeki iletiler erişme, bu iletileri eleştirel bir süzgeçten geçirerek çözümleme, değerlendirme ve kendi iletilerini sorumlu biçimde üretme yetkinliğine ne ad verilir?', 'Medya okuryazarlığı', ['Bilgisayar programcılığı', 'Grafik tasarım uzmanlığı', 'Kurumsal halkla ilişkiler'], '1992 Aspen Enstitüsü tanımına dayanan medya okuryazarlığı; medya mesajlarına erişme, onları eleştirel analiz etme, değerlendirme ve içerik üretme becerilerinin bütünüdür.'),
  ('İnternet sitelerini ziyaret eden kullanıcıların tarayıcılarına bırakılan ve oturum bilgilerini, dil tercihlerini veya reklam izleme geçmişini kaydeden küçük veri dosyalarına ne ad verilir?', 'Çerez (Cookie)', ['Güvenlik duvarı (Firewall)', 'Açık kaynak kodu', 'Alan adı sunucusu'], 'HTTP çerezleri (cookies), özellikle üçüncü taraf takip çerezleri olduğunda kullanıcının farklı sitelerdeki gezinme alışkanlıklarını izleyerek hedefli reklam profili çıkarmakta kullanılır.'),
  ('Güvenilir bir banka, kargo şirketi veya resmî kurumdan geliyormuş süsü verilen sahte e-posta ve mesajlarla kullanıcıların şifre ve kredi kartı bilgilerini ele geçirme yöntemine ne ad verilir?', 'Phishing (Oltalama)', ['Trolling (Trolleme)', 'Streaming (Akış yayını)', 'Blogging (Günlük yazarlığı)'], 'Dijital okuryazarlığın temel güvenlik konularından biri olan oltalama (phishing), sosyal mühendislik ve aciliyet hissi kullanarak kurbanı sahte bir giriş sayfasına yönlendirir.'),
  ('Sosyal medyada toplumsal veya çevresel sorunlara yalnızca oturduğu yerden beğeni yaparak, etiket paylaşarak ya da profil fotoğrafı değiştirerek katılıp gerçek hayatta hiçbir çaba göstermeme durumuna ne denir?', 'Slacktivizm', ['Sivil itaatsizlik eylemi', 'Araştırmacı gazetecilik', 'Transmedya aktivizmi'], '"Slacker" (tembel/miskin) ve "activism" kelimelerinden türetilen slacktivizm (veya clicktivism), düşük maliyetli çevrimiçi jestlerle vicdani tatmin sağlayıp somut eylemden kaçınmayı eleştirir.'),
  ('Bir gazetecinin herhangi bir resmî sansür kurulu kararı olmadan, işini kaybetme, dava edilme veya hedef gösterilme endişesiyle kendi haberini bizzat kendisinin törpülemesine ya da hiç yazmamasına ne denir?', 'Otosansür', ['Yayın yasağı', 'Tekzip hakkı', 'Editöryal düzeltme'], 'Otosansür, dışsal baskıların gazeteci zihninde içselleştirilmesiyle muhabirin veya editörün "bu haberi yazarsam başım derde girer" diyerek kendi kalemini kısıtlamasıdır.'),
  ('Basında veya internet haber sitelerinde bir kişi ya da kurum hakkında gerçeğe aykırı, şeref ve haysiyeti zedeleyici bir yayın yapıldığında mağdur tarafın yayımlatma hakkına sahip olduğu düzeltme metnine ne denir?', 'Tekzip', ['Manşet altı spotu', 'Sürmanşet ilanı', 'Editörün mektubu'], 'Basın hukukunda "cevap ve düzeltme hakkı" olarak düzenlenen tekzip, gerçeğe aykırı yayından zarar gören kişi veya kurumun kendi açıklamasını aynı mecrada yayımlatabilmesini güvence altına alır.'),
  ('Gazete, dergi veya haber sitelerinde gerçek haberlerle birebir aynı sayfa tasarımına sahip olan, reklam olduğu küçük bir ibare dışında kolayca fark edilmeyen ücretli tanıtım içeriklerine ne ad verilir?', 'Doğal reklam / Advertorial', ['Kamu spotu bildirimi', 'Editöryal başyazı', 'Bağımsız köşe yazısı'], '"Advertisement" (reklam) ve "editorial" (editöryal yazı) kelimelerinin birleşimi olan advertorial (veya dijitaldeki doğal reklam / native advertising), ticari tanıtımı haber formatına gizleyerek okur güveninden yararlanır.'),
  ('Sosyal medyada gündemi kaçırma, arkadaşlarının katıldığı etkinliklerden veya anlık gelişmelerden habersiz kalma endişesiyle telefon ekranını sürekli kontrol etme dürtüsüne ne ad verilir?', 'FOMO (Gelişmeleri kaçırma korkusu)', ['JOMO (Kaçırmanın keyfi)', 'Dijital detoks uygulaması', 'Bilişsel çerçeveleme'], '"Fear of Missing Out" ifadesinin kısaltması olan FOMO, bireyin sosyal ağlardaki akışı kaçırma kaygısıyla kompulsif biçimde bildirimlere ve haber akışına bağımlı hale gelmesini açıklar.'),
  ('Claude Shannon ve Warren Weaver tarafından 1949 yılında geliştirilen doğrusal iletişim modelinde, sinyalin kanal üzerinden taşınırken bozulmasına yol açan dışsal müdahalelere ne ad verilir?', 'Gürültü', ['Geri bildirim mekanizması', 'Ortak yaşantı alanı', 'Semantik kod çözümü'], 'Shannon-Weaver modelinde iletişim sürecini kesintiye uğratan veya sinyali bozan her türlü parazit gürültü olarak adlandırılır.'),
  ('Harold Lasswell\'in iletişim sürecini özetleyen ünlü formülünde "Kim, neyi, hangi kanalla, kime söylüyor?" sorularını tamamlayan son öğe aşağıdakilerden hangisidir?', 'Hangi etkiyle', ['Hangi gürültü ortamında', 'Hangi ortak deneyimle', 'Hangi kodlama sistemiyle'], 'Lasswell\'in 1948 tarihli doğrusal formülü "Kim, neyi, hangi kanalla, kime, hangi etkiyle söylüyor?" şeklindedir.'),
  ('Antropolog Edward T. Hall tarafından ortaya atılan ve insanların iletişim sırasında kişiler arası mesafeyi nasıl kullandığını inceleyen çalışma alanına ne ad verilir?', 'Proksemik', ['Kinesik', 'Haptik', 'Kronemik'], 'Proksemik, iletişimde mekan ve fiziksel mesafe kullanımını kültürler arası boyutta inceleyen disiplindir.'),
  ('Edward T. Hall\'un proksemik sınıflandırmasına göre, yalnızca çok yakın aile üyeleri ve duygusal partnerlerin kabul edildiği (yaklaşık 0-45 cm arası) alan hangisidir?', 'Mahrem mesafe', ['Kişisel mesafe', 'Sosyal mesafe', 'Kamusal mesafe'], 'Hall\'un sınıflandırmasında cilde temas ihtimalinin yüksek olduğu 0-45 cm arası bölge mahrem mesafe olarak tanımlanır.'),
  ('Psikolog Thomas Gordon tarafından geliştirilen ve bireyin karşı tarafı suçlamadan kendi duygularını ve gereksinimlerini ifade etmesine dayanan iletişim biçimine ne ad verilir?', 'Ben dili', ['Sen dili', 'Yansıtıcı dil', 'Emredici dil'], 'Ben dili, davranışı yapan kişiyi yargılamak yerine davranışın konuşmacı üzerindeki somut etkisini ve yarattığı duyguyu açıklar.'),
  ('Randevusuna bir saat geç gelen arkadaşına "Her zaman sorumsuz davranıyorsun!" demek yerine "Seni bir saattir beklediğim ve haber alamadığım için endişelendim" diyen biri hangi iletişim becerisini kullanmaktadır?', 'Ben dili', ['Sen dili', 'Pasif dinleme', 'Savunmacı tepki'], 'Davranışı, somut etkiyi ve hissedilen duyguyu suçlayıcı sıfat kullanmadan ifade etmek ben dilinin temel yapısıdır.'),
  ('İletişim sürecinde zihindeki duygu, düşünce veya bilginin harf, sözcük, resim ya da işaret gibi sembollere dönüştürülmesi işlemine ne ad verilir?', 'Kodlama', ['Kod açma', 'Geri bildirim', 'Gürültü'], 'Kaynağın zihinsel içeriği paylaşılabilir sembolik biçimlere çevirmesi kodlama (encoding) aşamasıdır.'),
  ('Alıcının kaynaktan gelen iletiye verdiği sözlü veya sözsüz yanıta iletişim modellerinde ne ad verilir?', 'Geri bildirim', ['Kanal kapasitesi', 'Enformasyon entropisi', 'Referans çerçevesi'], 'Alıcının mesajı alıp almadığını ve nasıl yorumladığını kaynağa gösteren tepki geri bildirimdir (feedback).'),
  ('Sözsüz iletişimde dokunma davranışlarının (el sıkışma, sırt sıvazlama, sarılma vb.) sosyal ve psikolojik anlamlarını inceleyen alt alan hangisidir?', 'Haptik', ['Kronemik', 'Vokalik', 'Okülesik'], 'Haptik (dokunsal iletişim), fiziksel temasın kültür ve ilişki türüne göre taşıdığı mesajları araştırır.'),
  ('İletişimde zamanın algılanması, kullanılması ve yapılandırılmasının (dakiklik, bekletme süresi, konuşma sırası vb.) sözsüz mesaj olarak incelenmesine ne ad verilir?', 'Kronemik', ['Kinesik', 'Proksemik', 'Semiyotik'], 'Kronemik, zaman kullanımının statü, saygı ve öncelik gibi sözsüz anlamlar ürettiğini ortaya koyar.'),
  ('Karşımızdaki kişinin kendisini suçlu, kıstırılmış veya değersiz hissetmesine yol açarak savunmaya geçmesine neden olan "Sen zaten hep böylesin!" tarzı iletişim diline ne ad verilir?', 'Sen dili', ['Ben dili', 'Empatik dil', 'Betimleyici dil'], 'Sen dili kişiliğe yönelik genelleme ve yargılama içerdiği için direnç ve savunmacılık üretir.'),
  ('Dinleyicinin bedensel olarak ortamda bulunup göz teması kuruyormuş gibi görünmesine karşın zihninin başka düşüncelerde olduğu dinleme türüne ne ad verilir?', 'Görünüşte dinleme', ['Etkin dinleme', 'Empatik dinleme', 'Eleştirel dinleme'], 'Görünüşte (sahte) dinlemede birey onaylar gibi başını sallasa bile mesajı zihinsel olarak işlemez.'),
  ('İletişimde göz teması kurma süresi, bakış yönü ve göz bebeği tepkilerinin taşıdığı sözsüz anlamları inceleyen çalışma alanına ne ad verilir?', 'Okülesik', ['Haptik', 'Proksemik', 'Kronemik'], 'Okülesik (göz iletişimi), bakışların düzenleyici, duygusal ve kültürel işlevlerini araştıran sözsüz iletişim dalıdır.'),
  ('Bir öğrencinin derste konuyu anlamadığı halde çekindiği için öğretmenin "Anlaşıldı mı?" sorusuna başını yukarı aşağı sallayarak yanıt vermesi iletişim sürecinde ne tür bir öğedir?', 'Sözsüz geri bildirim', ['Mekanik gürültü', 'Kaynak kodlaması', 'Kamusal mesafe'], 'Öğrenci alıcı konumunda kaynağın sorusuna beden hareketiyle yanıt verdiği için bu bir sözsüz geri bildirimdir.'),
  ('Bir tiyatro oyuncusunun sahnede hiç konuşmadan yalnızca omuzlarını çökertip başını öne eğerek derin bir kederi seyirciye aktarması hangi sözsüz iletişim kanalının kullanımıdır?', 'Postür (beden duruşu)', ['Kronemik (zaman kullanımı)', 'Haptik (dokunsal temas)', 'Grafiksel sembolizm'], 'Vücudun genel duruş biçimi, omuz ve omurga pozisyonu postür olarak adlandırılır ve duygusal durumu güçlü biçimde yansıtır.'),
  ('Konuşmacının anlattıklarını dinlerken "Hı-hı", "Anlıyorum", "Evet" gibi kısa sözel tepkilerle ve baş sallamayla konuşmayı sürdürmesini teşvik etmeye ne ad verilir?', 'Kapı aralayıcılar / onaylayıcı tepkiler', ['İletişim engelleri', 'Savunmacı yargılamalar', 'Mekanik parazitler'], 'Etkin dinlemede kısa onay tepkileri ve "Devam et, seni dinliyorum" türünden kapı aralayıcılar konuşmacının kendini açmasını kolaylaştırır.'),
  ('Bir konuşmacının "Şu kadar büyüktü" derken iki elini iki yana açarak nesnenin boyutunu göstermesi Ekman ve Friesen\'e göre hangi tür beden hareketidir?', 'Açıklayıcılar (illüstratörler)', ['Adaptörler (uyarlayıcılar)', 'Amblemler', 'Semantik gürültüler'], 'Sözel mesaja eşlik eden, söylenen sözü somutlaştıran veya vurgulayan el-kol hareketlerine açıklayıcılar (illustrators) denir.'),
  ('"Empatik dinleme" ile "sempatik tepki verme" arasındaki en temel fark aşağıdakilerden hangisidir?', 'Empatide kişinin duygusunu onun bakış açısından anlamak esasken, sempatide kişiyle aynı duyguyu paylaşıp taraf olmak söz konusudur', ['Empatide konuşmacının tüm hataları yüzüne vurulurken, sempatide konuşmacı hiç dinlenmez', 'Empati yalnızca yazılı metinlerde kurulabilirken, sempati yalnızca telefon görüşmelerinde gerçekleşir', 'Empatide dinleyici sürekli öğüt verirken, sempatide dinleyici tamamen sessiz kalır'], 'Empati "kendini ötekinin yerine koyarak nesnel anlayış geliştirmek", sempati ise "ötekiyle duygudaş olup onunla birlikte üzülmek/sevinmek ve yandaş olmaktır".'),
  ('Sözsüz iletişimin sözlü iletişimle ilişkisinde, "Evet, kabul ediyorum" derken aynı anda başı yukarı aşağı sallamak sözsüz davranışın hangi işlevini gösterir?', 'Tekrarlama / pekiştirme', ['Çelişme / yalanlama', 'İkame etme', 'Kanal kapatma'], 'Sözel olarak ifade edilen mesajın beden diliyle aynı anda desteklenmesi tekrarlama veya pekiştirme işlevidir.'),
  ('İletişim sürecinde mesajın kaynaktan alıcıya ulaşmasını sağlayan ışık, ses dalgaları, kağıt, telefon hattı veya televizyon ekranı gibi araçlara genel olarak ne ad verilir?', 'Kanal', ['Kod açıcı', 'Referans çerçevesi', 'Entropi kaynağı'], 'Mesajın fiziksel olarak taşındığı ortam veya araç iletişim modellerinde kanal (channel/medium) olarak tanımlanır.'),
  ('Dinleme sürecinde "işitme" ile "dinleme" arasındaki farkı en doğru açıklayan ifade aşağıdakilerden hangisidir?', 'İşitme ses dalgalarının kulağa çarpmasıyla oluşan fizyolojik bir süreçken, dinleme dikkat ve anlamlandırma gerektiren zihinsel bir etkinliktir', ['İşitme yalnızca müzik sesleri için kullanılırken, dinleme yalnızca insan sesi için kullanılır', 'İşitme bilinçli bir çaba gerektirirken, dinleme uyku sırasında bile kendiliğinden gerçekleşen bir reflekstir', 'İşitme yüz yüze iletişimde gerçekleşirken, dinleme yalnızca kitle iletişim araçlarında görülür'], 'İşitme biyolojik ve pasif bir duyusal algılama iken, dinleme seçme, odaklanma ve yorumlama içeren aktif bilişsel bir süreçtir.'),
  ('Yüz ifadeleriyle ortaya çıkan mutluluk, öfke, korku, şaşkınlık, tiksinme ve üzüntü gibi temel duyguların tüm kültürlerde benzer mimiklerle tanındığını gösteren ünlü araştırmacı kimdir?', 'Paul Ekman', ['Harold Lasswell', 'Claude Shannon', 'David Berlo'], 'Paul Ekman, izole kabileler dahil farklı kültürlerde yaptığı çalışmalarla temel yüz ifadelerinin evrensel biyolojik kökleri olduğunu kanıtlamıştır.'),
  ('Paul Lazarsfeld, Bernard Berelson ve Hazel Gaudet\'in 1940 ABD başkanlık seçimlerini inceleyerek kitle iletişim mesajlarının halka doğrudan değil aracılar üzerinden ulaştığını ortaya koydukları kuram hangisidir?', 'İki aşamalı akış kuramı', ['Sihirli mermi kuramı', 'Suskunluk sarmalı kuramı', 'Ekme (yetiştirme) kuramı'], 'Halkın Seçimi (The People\'s Choice) araştırmasıyla ortaya konan model, mesajların medyadan kanaat önderlerine, onlardan da diğer bireylere aktığını gösterir.'),
  ('İki aşamalı iletişim akışı modelinde, medyayı yakından takip ederek edindikleri bilgileri kendi sosyal çevrelerindeki insanlara yorumlayarak aktaran etkili kişilere ne ad verilir?', 'Kanaat önderleri (fikir liderleri)', ['Eşik bekçileri (editörler)', 'Kültür endüstrisi teknisyenleri', 'Pasif kitle alıcıları'], 'Kanaat önderleri (opinion leaders), birincil gruplar içinde güven duyulan ve medya iletilerini süzerek çevrelerini etkileyen bireylerdir.'),
  ('"Medya insanlara ne yapıyor?" sorusu yerine "İnsanlar medyayla ne yapıyor?" sorusunu merkeze alan iletişim yaklaşımı aşağıdakilerden hangisidir?', 'Kullanımlar ve doyumlar kuramı', ['Kültür endüstrisi kuramı', 'Gündem belirleme kuramı', 'Propaganda modeli'], 'Elihu Katz, Jay Blumler ve Michael Gurevitch\'in sistemleştirdiği kullanımlar ve doyumlar yaklaşımı aktif izleyiciyi merkeze alır.'),
  ('Kullanımlar ve doyumlar kuramının izleyici kitlesine bakış açısını en doğru özetleyen temel varsayım aşağıdakilerden hangisidir?', 'İzleyiciler kendi psikolojik ve sosyal ihtiyaçlarını karşılamak üzere medya içeriklerini bilinçli biçimde seçen aktif öznelerdir', ['İzleyiciler medya tarafından gönderilen her türlü ideolojik mesajı sorgulamadan kabul eden edilgen yığınlardır', 'İzleyicilerin medya tercihlerini bireysel gereksinimler değil, yalnızca yayın sinyallerinin fiziksel gücü belirler', 'İzleyiciler kitle iletişim araçlarını yalnızca devlet zoruyla ve yasal yükümlülük nedeniyle takip eder'], 'Bu yaklaşıma göre izleyici pasif bir hedef değil, amaç yönelimli ve seçici bir medya kullanıcısıdır.'),
  ('"Kültür Endüstrisi" kavramı, 1947\'de yayımlanan "Aydınlanmanın Diyalektiği" adlı eserde hangi iki Frankfurt Okulu düşünürü tarafından ortaya atılmıştır?', 'Max Horkheimer ve Theodor W. Adorno', ['Paul Lazarsfeld ve Robert K. Merton', 'Marshall McLuhan ve Harold Innis', 'Claude Shannon ve Warren Weaver'], 'Horkheimer ve Adorno, kültürün kapitalist seri üretim mantığıyla metalaştırılmasını açıklamak için "kültür endüstrisi" kavramını geliştirmiştir.'),
  ('İletişim kuramında "Araç mesajdır" (The medium is the message) ve "Küresel köy" (Global village) kavramlarıyla tanınan Kanadalı düşünür kimdir?', 'Marshall McLuhan', ['Theodor W. Adorno', 'Elihu Katz', 'Wilbur Schramm'], 'Toronto Okulu\'nun önde gelen ismi Marshall McLuhan, iletişim teknolojilerinin kendisinin toplumsal algıyı biçimlendirdiğini savunmuştur.'),
  ('Marshall McLuhan\'ın ünlü "Araç mesajdır" (The medium is the message) önermesiyle anlatmak istediği temel düşünce aşağıdakilerden hangisidir?', 'Toplumları ve insan algısını asıl dönüştüren şey iletişim aracının taşıdığı içerikten ziyade, bizzat o aracın kendi teknolojik yapısı ve yarattığı yeni ölçeklerdir', ['Televizyon ve radyo kanallarında yayınlanan haber metinlerinin hiçbir siyasi veya kültürel anlam taşımadığıdır', 'Gazetecilerin haber yazarken kullandıkları daktilo markasının haberin doğruluğunu yüzde yüz kanıtladığıdır', 'İnsanların iletişim kurmak için artık konuşmayı bırakıp yalnızca teknolojik cihazların resimlerine baktığıdır'], 'McLuhan\'a göre örneğin matbaa ya da televizyon, içinde ne anlatıldığından bağımsız olarak insanın duyusal dengesini, zaman-mekan algısını ve örgütlenme biçimini değiştirir.'),
  ('McLuhan\'ın hocası olan, imparatorlukların yükseliş ve çöküşünü kullandıkları iletişim araçlarının "zaman yanlı" (kil tablet, taş) veya "mekan yanlı" (papirüs, kağıt) olmasına bağlayan Toronto Okulu kuramcısı kimdir?', 'Harold Innis', ['Herbert Marcuse', 'Bernard Berelson', 'Thomas Gordon'], 'Harold Innis, "İmparatorluk ve İletişim" adlı eserinde dayanıklı araçların zaman üzerinde, hafif ve taşınabilir araçların ise geniş coğrafi mekanlar üzerinde denetim kurduğunu göstermiştir.'),
  ('İki aşamalı akış modelinin daha sonraki araştırmalarla geliştirilerek kanaat önderlerinin de başka kanaat önderlerinden etkilendiğinin ve bilginin çok yönlü ağlarda dolaştığının gösterildiği modele ne ad verilir?', 'Çok aşamalı akış modeli', ['Tek aşamalı şırınga modeli', 'Doğrusal telgraf modeli', 'Suskunluk çemberi modeli'], 'İletişim ağlarının karmaşıklığı anlaşıldıkça iki aşamalı model, bilginin birden fazla aracı halkadan geçtiği "çok aşamalı akış" (multi-step flow) modeline evrilmiştir.'),
  ('Kullanımlar ve doyumlar araştırmalarının öncülerinden Herta Herzog, 1940\'lı yıllarda hangi medya türünün kadın dinleyicilere sağladığı duygusal boşalma ve tavsiye alma doyumlarını incelemiştir?', 'Gündüz kuşağı radyo arkası yarınlarını', ['Uluslararası finans gazetelerinin borsa sayfalarını', 'Sessiz sinema döneminin belgesel filmlerini', 'Telgraf hatlarıyla iletilen askeri bültenleri'], 'Herta Herzog\'un radyo pembe dizisi (soap opera) dinleyicileri üzerine yaptığı çalışma, kullanımlar ve doyumlar geleneğinin kurucu araştırmalarından biridir.'),
  ('Frankfurt Okulu düşünürlerinden Herbert Marcuse\'nin, kültür endüstrisi ve tüketim toplumu tarafından yapay ihtiyaçlarla bütünleştirilerek eleştiri yetisi köreltilmiş modern bireyi tanımladığı ünlü eseri hangisidir?', 'Tek Boyutlu İnsan', ['Gutenberg Galaksisi', 'Kişisel Etki', 'Sessiz Dil'], 'Herbert Marcuse, 1964 tarihli "Tek Boyutlu İnsan" (One-Dimensional Man) kitabında ileri sanayi toplumunun muhalefeti ve eleştirel düşünceyi nasıl erittiğini inceler.'),
  ('Marshall McLuhan\'ın fonetik alfabenin ve özellikle Johannes Gutenberg\'in hareketli harfli matbaasının Batı medeniyetinde yarattığı görsel, doğrusal ve bireyci kültür çağını incelediği kitabı hangisidir?', 'Gutenberg Galaksisi', ['Aydınlanmanın Diyalektiği', 'Halkın Seçimi', 'İletişimin Matematiksel Kuramı'], 'McLuhan 1962 tarihli "Gutenberg Galaksisi: Tipografik İnsanın Oluşumu" eserinde matbaa kültürünün sonuçlarını analiz eder.'),
  ('Bir gıda firmasının yeni ürününü tanıtırken doğrudan televizyon reklamına yüklenmek yerine sosyal çevresinde sözü dinlenen beslenme uzmanlarına ve yerel topluluk öncülerine ürünü denetmesi hangi kuramın stratejik uygulamasıdır?', 'İki aşamalı akış ve kanaat önderliği yaklaşımının', ['Shannon-Weaver mekanik gürültü azaltma kuramının', 'Adorno\'nun otantik sanat eseri savunusunun', 'Hall\'un kamusal mesafe koruma ilkesinin'], 'Pazarlama ve halkla ilişkilerde "influencer / fikir lideri" kullanımı doğrudan Lazarsfeld ve Katz\'ın iki aşamalı akış modeline dayanır.'),
  ('Frankfurt Okulu (Toplumsal Araştırmalar Enstitüsü) 1923 yılında hangi ülkede kurulmuş ve Nazi iktidarının yükselişiyle birlikte çalışmalarını ABD\'ye taşımıştır?', 'Almanya', ['Kanada', 'Fransa', 'İngiltere'], 'Frankfurt Okulu Almanya\'nın Frankfurt kentinde kurulmuş, 1930\'larda Cenevre üzerinden New York\'a (Columbia Üniversitesi bünyesine) göç etmiştir.'),
  ('Marshall McLuhan\'ın teknolojik belirlenimcilik (technological determinism) yaklaşımına göre toplumsal değişimin birincil itici gücü aşağıdakilerden hangisidir?', 'İletişim ve medya teknolojilerinde meydana gelen yenilikler', ['Siyasi liderlerin seçim meydanlarında yaptıkları konuşmalar', 'Bireylerin doğuştan getirdikleri değişmez genetik mizaçları', 'Mevsimsel sıcaklık değişimleri ve yıllık yağış miktarları'], 'Teknolojik belirlenimcilik, baskın iletişim teknolojisinin insanların nasıl düşündüğünü, hissettiğini ve toplumsal kurumları nasıl örgütlediğini belirlediğini ileri sürer.'),
  ('İletişim modellerinde kaynaktan çıkan mesajın alıcı tarafından çözülürken kaynağın niyetinden farklı bir biçimde anlaşılmasına genel olarak ne ad verilir?', 'İletişim kazası / yanlış kod açımı', ['Tam simetrik uzlaşma', 'Mekanik sinyal güçlendirme', 'Kanaat önderliği devri'], 'Kaynağın kodladığı anlam ile alıcının referans çerçevesine göre çözdüğü anlamın uyuşmaması yanlış kod açımı veya sapmalı okumadır.'),
  ('İletişimde "empati" kavramını açıklarken kullanılan "bir başkasının ayakkabılarını giyerek yürümek, ama o ayakkabıların kendisine ait olmadığını da unutmamak" benzetmesi neyi vurgular?', 'Karşı tarafın duygu ve düşüncesini onun açısından anlarken kendi benlik sınırımızı ve nesnelliğimizi kaybetmemeyi', ['Dinlediğimiz kişinin tüm maddi sorumluluklarını ve borçlarını kendi üzerimize almayı', 'Karşı taraf haksız olduğunda bile onunla birlikte başkalarına saldırmayı', 'İletişim sırasında kendi duygularımızı tamamen bastırarak hiç konuşmamayı'], 'Carl Rogers\'ın belirttiği gibi empati, "sanki o kişiymiş gibi" hissetmek ama bu "sanki" (as if) niteliğini yitirmeden, yani sempatiye ve özdeşleşmeye kapılmadan anlamaktır.'),
  ('Sözsüz iletişimde sesin tonu, tınısı, yüksekliği, konuşma hızı, iç çekmeler ve duraksamalar gibi sese dayalı ancak kelimenin sözlük anlamı dışındaki unsurlara ne ad verilir?', 'Paralinguistik (vokalik / dil ötesi) öğeler', ['Proksemik (mekansal) öğeler', 'Artefakt (nesnel) öğeler', 'Haptik (dokunsal) öğeler'], 'Ne söylediğimiz sözel (linguistik), onu nasıl bir ses tonu ve vurguyla söylediğimiz ise paralinguistik (dil ötesi) alana girer.'),
  ('İletişim kuramlarında bir mesajın kitlelere tıpkı derinin altına zerk edilen bir ilaç gibi doğrudan, anında ve tek tip etki yaptığı varsayımına dayanan erken dönem modele ne ad verilir?', 'Hipodermik iğne (şırınga / sihirli mermi) modeli', ['Kullanımlar ve doyumlar modeli', 'İki aşamalı akış modeli', 'Dairesel etkileşim modeli'], 'İki dünya savaşı arası dönemde propaganda korkusuyla gelişen bu görüş; hipodermik şırınga, deri altı iğne veya sihirli mermi adlarıyla anılır.'),
  ('İyi bir dinleyicinin konuşmacı sözünü bitirdikten hemen sonra birkaç saniye sessiz kalarak bekleyebilmesi etkin dinlemede nasıl bir yarar sağlar?', 'Konuşmacıya düşüncelerini toparlama ve asıl söylemek istediği derin duyguları ekleme fırsatı verir', ['İletişim kanalında mekanik bir arıza olduğunu düşündürerek konuşmayı sonlandırır', 'Dinleyicinin konuyu hiç anlamadığını göstererek konuşmacıyı utandırır', 'Aralarındaki kişisel mesafeyi bir anda kamusal mesafeye çıkarır'], 'Yapıcı sessizlik (bekleme süresi), konuşmacının aceleye getirilmediğini hissetmesini ve yüzeysel ifadenin altındaki asıl duyguyu paylaşmasını kolaylaştırır.'),
];
